//! Task help stays available without network access or the source checkout.
use eframe::egui;

pub(super) fn show(ui: &mut egui::Ui) {
    ui.label("Use these steps to import, prepare, analyse and report your data. This guide is available offline.");
    let sections = [
        ("Import and inspect", "Import .xlsx, CSV or TSV, then review column names, types and sample values. CSV/TSV use the first row as variable names. Keep identifiers as Text when their exact spelling matters. Changing the delimiter resets column choices: review them again.\nFor Excel, choose a worksheet, range and header setting, then review it. Stored numbers and cached formula values may already be rounded or out of date. Tessera does not execute formulas, macros or external links.\nBlank numeric cells are missing. Empty text can be valid unless explicitly declared missing. Review that choice before reporting percentages."),
        ("Edit and navigate data", "Select a cell and use arrows to move. Enter starts editing; Tab and Shift+Tab advance; Escape cancels. Inspect cell exposes the exact value; Copy preserves numeric precision. Drag a column header's right edge to resize it.\nPaste tab-separated values into existing cells, up to 4,096 cells and 512 KiB. The entire rectangle is validated before changing cells. Use Variables for descriptions, measurement levels and missing definitions; apply or discard pending property changes before continuing."),
        ("Prepare and undo", "Compute, Recode and Mean / Domain average add a variable. Sort changes row order; Filter removes rows from the current dataset. Use a unique output name. After applying, inspect Data or use Undo.\nSurvey label preparation previews exact changes and creates a reviewed column while retaining the original. Trimming precedes exact replacements; letter case is not changed automatically. Undo restores earlier data, but does not itself save the project."),
        ("Choose an analysis", "Help choose an analysis asks about the question, outcome and relationship between observations. A recommendation opens a form; it never runs a test. Unsupported or unclear designs need further review. Linear regression and scale reliability also have their own forms.\nGuided keeps detailed options under More settings; Advanced shows them directly. Both use the same calculations. Select variables and inspect the actual filter and frequency weight before Run. Required fields being complete does not establish suitability: check method assumptions. Frequency weights represent repeated observations, not survey probability weights."),
        ("Analysis history and report contents", "Results retains outputs, captured definitions and analysis settings, not a complete copy of every earlier dataset. A changed-data marker means the result came from another revision. Rerun against the intended data when necessary.\nReusing settings and running again appends a history entry. Continuing preserves choices; a fresh analysis starts with defaults. All-results export includes all history; selected-results export includes your explicit selection. The survey batch shortcut is temporary: select the intended runs again after reopening."),
        ("Create a survey report", "Review reporting roles and the included/excluded summary. Count responses treats complete cells as categories. Summarise a measurement creates summaries and a histogram. Leave out retains the variable in the dataset. Check blank-response rules and reviewed-copy relationships.\nPersonal-data and duplicate warnings are advisory. Rows are retained; multiple-answer cells are not silently split. The automatic report is descriptive and unweighted. It does not infer repeated measurements, choose inferential tests or score questionnaires. A report recipe is separate from the project and requires matching source names and types."),
        ("Figures and export", "Select a result, expand Figures and choose a chart. Edit appearance, inspect the preview, then Apply figure. Apply changes the project; save it to retain changes on disk. PNG is the default; SVG is available for vector output.\nReports export as HTML. Use new export filenames; existing files are protected. Batch figures need a new folder or filenames that do not already exist. Partial export can leave completed files: inspect error details and the destination before retrying."),
        ("Save, recover and find files", "Unsaved project means there is no project file yet. Unsaved changes means the project differs from its saved version. Save retains data, definitions, preparation, results and figure settings in a .tessera file. Exporting a report or image does not save the project.\nFile details identifies explicit saves/exports; Recovery details identifies protective recovery work and warnings. A checkpoint is separate from your project and does not mean it was saved. Keep protective files when publication or cleanup is uncertain.\nSave as to the current project retains conflict protection. For another destination, choose a new filename. Windows crash recovery is unavailable. Legacy recovery folders are not automatically swept."),
        ("Export data to a spreadsheet", "CSV/TSV preserves text exactly. Some text or names can be interpreted as spreadsheet formulas. When warned, use Excel or LibreOffice's text-import route, set imported columns to Text, and do not enable external content. CSV quotes alone do not prevent formula evaluation. Keep a .tessera project to retain metadata and results."),
        ("Appearance and keyboard access", "View offers System, Light and Dark appearance and interface size. Reset size returns to 100%. Navigation adapts to smaller windows. In Analyse, Command+Enter on Mac or Ctrl+Enter elsewhere runs the completed form. Cancel operation requests cancellation; wait for confirmation before starting replacement work."),
    ];
    for (index, (title, text)) in sections.iter().enumerate() {
        egui::CollapsingHeader::new(*title)
            .id_salt(("user-guide", index))
            .default_open(index == 0)
            .show(ui, |ui| {
                for paragraph in text.split('\n') {
                    ui.label(paragraph);
                    ui.add_space(4.);
                }
            });
    }
}
